mapper.update:
UPDATE repair_records
mold_id = #{moldId}, reporter_id = #{reporterId}, maintainer_id = #{maintainerId}, verifier_id = #{verifierId}, repair_reason = #{repairReason}, repair_description = #{repairDescription}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, cost = #{cost}, notes = #{notes}, repair_approval_status = #{repairApprovalStatus}, repair_approval_comment = #{repairApprovalComment}, repair_approver_id = #{repairApproverId}, repair_approval_time = #{repairApprovalTime},
WHERE id = #{id}

mapper.select:
SELECT r.id, r.mold_id, m.mold_code, m.name AS mold_name, m.category AS mold_category, r.reporter_id, ur.real_name AS reporter_name, r.maintainer_id, um.real_name AS maintainer_name, r.verifier_id, uv.real_name AS verifier_name, r.repair_reason, r.repair_description, r.start_time, r.end_time, r.status, r.cost, r.notes, r.repair_approval_status, r.repair_approval_comment, r.repair_approver_id, r.repair_approval_time, r.created_at FROM repair_records r LEFT JOIN molds m ON r.mold_id = m.id LEFT JOIN users ur ON r.reporter_id = ur.id LEFT JOIN users um ON r.maintainer_id = um.id LEFT JOIN users uv ON r.verifier_id = uv.id
AND r.mold_id = #{moldId}
AND (m.mold_code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
AND r.reporter_id = #{reporterId}
AND r.maintainer_id = #{maintainerId}
AND r.verifier_id = #{verifierId}
AND r.start_time >= #{startTime}
AND r.end_time <= #{endTime}
AND r.status = #{status}
ORDER BY r.created_at DESC

mapper.update:
UPDATE repair_records
SET repair_approval_status  = #{status},
    repair_approval_comment = #{comment},
    repair_approver_id      = #{approverId},
    repair_approval_time    = #{approveTime}
WHERE id = #{id}

mapper.select:
SELECT mold_id FROM repair_records
WHERE start_time >= #{since}
GROUP BY mold_id
HAVING COUNT(1) >= #{threshold}
